            };

            // Derive backend hosted logo URLs for all institutions
            foreach (var fi in catalog)
            {
                fi.LogoUrl = $"https://mahfazati.runasp.net/images/banks/{fi.Id}.png";
            }

            var existing = await context.FinancialInstitutions.ToListAsync();
            var existingMap = existing.ToDictionary(fi => fi.Id, StringComparer.OrdinalIgnoreCase);

            var toAdd = new List<FinancialInstitution>();
            foreach (var item in catalog)
            {
                if (existingMap.TryGetValue(item.Id, out var existingFi))
                {
                    existingFi.LogoUrl = item.LogoUrl;
                    existingFi.LogoAsset = item.LogoAsset;
                    existingFi.Website = item.Website;
                }
                else
                {
                    toAdd.Add(item);
                }
            }

            if (toAdd.Count > 0)
            {
                await context.FinancialInstitutions.AddRangeAsync(toAdd);
            }
            await context.SaveChangesAsync();
        }
